// 根据图片路径判定花色顺序：m < p < s < 其它(z/ph等)
const suitRank = (imgPath) => {
  if (typeof imgPath !== 'string') return 3;
  if (imgPath.endsWith('m.png')) return 0;
  if (imgPath.endsWith('p.png')) return 1;
  if (imgPath.endsWith('s.png')) return 2;
  // honors(z) 或占位(ph/-1等) 统一放在最后
  return 3;
};

// 仅对 images2 的最后一张之前进行排序，最后一张保持不动
const sortImages2 = (images) => {
  if (!Array.isArray(images) || images.length <= 1) return images;
  const last = images[images.length - 1];
  const head = images.slice(0, -1).slice().sort((a, b) => suitRank(a) - suitRank(b));
  return [...head, last];
};

